private async pauseRun(runId: string, actor: Actor = SYSTEM_ACTOR): Promise<RunRecord> {
  const run = await this.mustGet(runId);
  const updated = await this.ports.runs.transition(runId, ['queued', 'running', 'waiting'], {
    status: 'paused',
    pausedAt: this.now(),
  });
  if (!updated) {
    throw new EngineRequestError('INVALID_STATE', `cannot pause a run that is ${run.status}`);
  }
  await this.ports.events.append(runId, [{ type: 'run.paused', actor }]);
  this.dequeue(runId);
  return updated;
}

private async recoveryState(
  runId: string,
  owningParent?: string,
): Promise<{ run: RunRecord; recovery: RunRecovery }> {
  let run: RunRecord | undefined;
  try {
    // Never attach a future history sequence to an older failure/consent target.
    const before = await this.mustGet(runId);
