191	  /** Problems that would stop a definition's triggers from arming: bad cron expressions or zones. */
192	  checkDefinition(definition: LoopDefinition): ValidationIssue[] {
193	    const issues: ValidationIssue[] = [];
194	    for (const node of nodesOfKind(definition, 'trigger')) {
195	      if (node.config.type !== 'cron') continue;
196	      const problem = CronScheduler.validate(node.config.expression, node.config.timezone);
197	      if (problem) {
198	        issues.push({
199	          code: 'CRON_INVALID',
200	          severity: 'error',
201	          message: `cron trigger "${node.id}": ${problem.message}`,
202	          nodeId: node.id,
203	          path: `config.${problem.field}`,
204	        });
205	      }
206	    }
207	    return issues;
