210	  /**
211	   * Make `version` the loop's armed version: one schedule per cron trigger node and one endpoint
212	   * per webhook trigger node, with rows of earlier versions disabled. Idempotent for the same
213	   * version, so boot can call it for every loop.
214	   */
215	  async armVersion(loop: LoopRecord, version: LoopVersionRecord): Promise<LoopTriggers> {
216	    const now = this.deps.clock.now();
217	    const triggers = nodesOfKind(version.definition, 'trigger');
218	    const cronDrafts: ScheduleDraft[] = [];
219	    const hookDrafts: WebhookEndpointDraft[] = [];
220	    for (const node of triggers) {
221	      const config = node.config;
222	      if (config.type === 'cron') {
223	        let next: Date | undefined;
224	        try {
225	          next = config.enabled
226	            ? CronScheduler.nextFire(config.expression, config.timezone, now)
227	            : undefined;
228	        } catch (error) {
229	          this.deps.logger.warn(
230	            { loopId: loop.id, nodeId: node.id, error: describe(error) },
231	            'cron trigger not armed',
232	          );
233	        }
234	        cronDrafts.push({
235	          ownerId: loop.ownerId,
236	          triggerNodeId: node.id,
237	          expression: config.expression,
238	          timezone: config.timezone,
239	          missedFirePolicy: config.missedFirePolicy,
240	          enabled: config.enabled && next !== undefined,
241	          nextFireAt: next?.toISOString(),
242	        });
243	      } else if (config.type === 'webhook') {
244	        hookDrafts.push({
245	          ownerId: loop.ownerId,
246	          triggerNodeId: node.id,
247	          authentication: config.authentication,
248	        });
249	      }
250	    }
251	    await this.deps.schedules.replaceForVersion(loop.id, version.id, cronDrafts);
252	    await this.deps.endpoints.replaceForVersion(loop.id, version.id, hookDrafts, () =>
253	      randomBytes(32).toString('base64url'),
254	    );
255	    this.deps.polls.arm(loop, version);
256	    return this.listForLoop(loop.id);
257	  }
