260	  async armAll(): Promise<number> {
261	    let armed = 0;
262	    for (const loop of await this.deps.loops.listPublished()) {
263	      try {
264	        const version = await this.deps.loops.getVersion(loop.currentVersionId as string);
265	        if (!version) continue;
266	        await this.armVersion(loop, version);
