private async resumeRun(
  run: RunRecord,
  observedSeq: number,
  actor: Actor = SYSTEM_ACTOR,
  retryUncertainScript?: true,
  childRecovery?: Extract<RunEvent, { type: 'run.resumed' }>['childRecovery'],
): Promise<RunRecord> {
  const runId = run.id;
  if (this.draining && !this.drainRuns.has(runId)) this.assertAdmissionOpen();
  if (this.forcing) this.assertAdmissionOpen();
  if (run.status === 'paused') {
    return this.withRunLock(runId, async () => {
      const current = await this.mustGet(runId);
      const events = await this.ports.events.read(runId);
      if (current.status !== 'paused' || (events.at(-1)?.seq ?? 0) !== observedSeq)
        throw new RecoveryRefusedError(
          'RECOVERY_STALE',
          'The run changed since it was shown. Refresh and review its current recovery choices.',
        );
      // The compare-and-set is the admission point. Keep the run paused until the intent
      // commits, so wakes, timers and child completion cannot observe a half-claimed wait.
      await this.ports.events.append(
        runId,
        [
          {
            type: 'run.resumed',
            actor,
            ...(childRecovery ? { childRecovery } : {}),
            ...(retryUncertainScript ? { retryUncertainScript } : {}),
          },
        ],
        { expectedLastSeq: observedSeq },
      );
      const resumed = await this.completePausedResume(runId);
      if (!resumed)
        throw new RecoveryRefusedError(
          'RECOVERY_STALE',
          'The run changed since it was shown. Refresh and review its current recovery choices.',
        );
      return resumed;
    });
  }
  if (
    run.status === 'failed' &&
    (run.failure?.resumable || (await childSessionRecovered(this.ports, run)))
  ) {
    // Leaving a terminal status: the intent is written first, like every terminal transition.
    // The finalization marker of the failure is cleared so the run's next terminal outcome is
    // finalized again; recovery completes a resume whose `run.resumed` is durable. It waits for
    // any finalizer of the failure still in flight, which would otherwise set the marker again.
    // The failure this command saw: its terminal event. Inside the lock the run must still be
    // in that same resumable failure, or the command lost to another one (a concurrent resume,
    // and possibly a newer outcome) and is rejected before it writes anything.
    const observed = terminalEvent(await this.ports.events.read(runId))?.seq;
    const resumed = await this.withRunLock(runId, async () => {
      const current = await this.mustGet(runId);
      const terminal = terminalEvent(await this.ports.events.read(runId));
      if (
        current.status !== 'failed' ||
        !(current.failure?.resumable || (await childSessionRecovered(this.ports, current))) ||
        terminal?.seq !== observed ||
        (await this.ports.events.recoveryFacts(runId, [])).observedSeq !== observedSeq
      ) {
        return undefined;
      }
      await this.ports.runs.clearFinalized(runId);
      await this.ports.events.append(
        runId,
        [
          {
            type: 'run.resumed',
            actor,
            ...(retryUncertainScript ? { retryUncertainScript } : {}),
            ...(childRecovery ? { childRecovery } : {}),
          },
        ],
        { expectedLastSeq: observedSeq },
      );
      return this.completeResume(runId);
    });
    if (!resumed) {
      throw new EngineRequestError('INVALID_STATE', `cannot resume a run that is ${run.status}`);
    }
    return resumed;
  }
  throw new EngineRequestError('INVALID_STATE', `cannot resume a run that is ${run.status}`);
}

/** Project an admitted paused Resume; the caller holds the run lock (also during startup). */
private async completePausedResume(runId: string): Promise<RunRecord | undefined> {
  const events = await this.ports.events.read(runId);
  if (!pendingResume(events)) return undefined;
  const parked = parkedWait(events);
  const updated = await this.ports.runs.transition(
    runId,
    ['paused'],
    {
      status: parked ? 'waiting' : 'running',
      pausedAt: undefined,
      ...(parked
        ? { waiting: parked.wait, currentNodeId: parked.wait.nodeId }
        : { failure: undefined, finishedAt: undefined }),
    },
    { observedSeq: events.at(-1)?.seq ?? 0 },
  );
  if (!updated) return undefined;
  // No timer or child reconciliation is exposed before both the intent and status exist.
  if (parked) {
    await this.rearmTimers(runId, parked.wait);
    await this.reconcileChild(updated);
  } else this.enqueue(runId);
  return this.mustGet(runId);
}

/** Explicitly abandon only the failed node's missing provider conversation (#265). */
async recoverSession(
  runId: string,
  nodeId: string,
  failureSeq: number,
  actor: Actor = SYSTEM_ACTOR,
): Promise<RunRecord> {
  return this.withWork(async () => {
    this.assertAdmissionOpen();
    return this.withRunLock(runId, async () => {
      const run = await this.mustGet(runId);
      const events = await this.ports.events.read(runId);
      const failed = terminalEvent(events);
      const missing = run.failure?.missingSession;
      const version = await this.ports.loops.getVersion(run.versionId);
      const node = version && nodeById(version.definition, nodeId);
      const visit = visitTurn(events, nodeId);
      if (
        run.status !== 'failed' ||
        run.failure?.code !== 'HARNESS_SESSION_MISSING' ||
        run.failure.nodeId !== nodeId ||
        run.currentNodeId !== nodeId ||
        failed?.type !== 'run.failed' ||
        failed.seq !== failureSeq ||
        !missing ||
        missing.visitId !== visit.visitId ||
        node?.kind !== 'inference' ||
        node.config.harness !== missing.harness
      )
        throw new EngineRequestError(
          'INVALID_STATE',
          'The observed missing-session failure is no longer current for this inference node',
        );
      const authored = events.find(
        (event) =>
          event.type === 'harness.turn' &&
          event.nodeId === nodeId &&
          event.visitId === visit.visitId &&
          event.promptKind === 'authored',
      );
      await this.ports.runs.clearFinalized(runId);
      // The choice, actor/time and resume intent commit in one event. Startup already completes
      // durable resumes; no transient flag or session-row rewrite can lose this decision.
      await this.ports.events.append(runId, [
        {
          type: 'run.resumed',
          actor,
          freshSession: {
            ...missing,
            nodeId,
            failureSeq,
            priorContextCarried: false,
            ...(authored?.type === 'harness.turn' ? { prompt: authored.prompt } : {}),
          },
        },
      ]);
      const resumed = await this.completeResume(runId);
      if (!resumed)
        throw new EngineRequestError('INVALID_STATE', 'The run changed during session recovery');
      return resumed;
    });
  });
}

/** Move a failed run whose resume is durable back to running and queue it. */
private async completeResume(runId: string): Promise<RunRecord | undefined> {
  const updated = await this.ports.runs.transition(runId, ['failed'], {
    status: 'running',
    pausedAt: undefined,
    failure: undefined,
    finishedAt: undefined,
  });
  if (updated) this.enqueue(runId);
  return updated;
}

async provideInput(
  runId: string,
  waitId: string,
  payload: JsonValue,
  actor: Actor = SYSTEM_ACTOR,
): Promise<RunRecord> {
  return this.withWork(() => this.provideRunInput(runId, waitId, payload, actor));
}

